source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    def has_horizontal_run(row):
        return any(row[c] != 0 and row[c] == row[c + 1] == row[c + 2]
                   for c in range(w - 2))

    horizontal_rows = [r for r in range(h) if has_horizontal_run(grid[r])]
    if not horizontal_rows:
        return out
    last_horizontal = max(horizontal_rows)
    marker_cols = [c for c in range(w)
                   if any(grid[r][c] != 0 for r in range(last_horizontal + 1, h))]

    for c in marker_cols:
        crossings = {}
        for r in horizontal_rows:
            if grid[r][c] == 0 and 0 < c < w - 1:
                left, right = grid[r][c - 1], grid[r][c + 1]
                if left != 0 and left == right:
                    crossings[r] = left
        seed_rows = [r for r in range(last_horizontal + 1, h) if grid[r][c] != 0]
        if not seed_rows:
            continue
        current = grid[max(seed_rows)][c]
        for r in range(h - 1, -1, -1):
            if r in crossings:
                current = crossings[r]
            out[r][c] = current
    return out
'''
